import re

def is_decimal(s: str) -> bool:
    # Pattern explanation:
    # optional sign ^[+-]?
    # integer part: either digits or empty (if decimal point present)
    # decimal point \.
    # exactly two digits after decimal \d{2}
    # no extra characters $ at end
    pattern = r'^[+-]?(\d+)?\.\d{2}$'
    if not isinstance(s, str):
        return False
    if 'e' in s.lower():
        return False
    return bool(re.match(pattern, s))

